// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    GasBurner helper;

    function setUp() public {
        c = new C();
        helper = new GasBurner();
    }

    function testFuzz_property(address actor, bytes calldata data) public {
        vm.assume(actor != address(0));
        vm.prank(actor);
        bool ok;
        try c.forward(address(helper), data) {
            ok = true;
        } catch {
            ok = false;
        }
        // Rule: a failed low-level subcall must propagate as a revert of forward.
        // Reference C: subcall OOGs -> require(_s) fails -> forward reverts -> ok == false.
        // Mutant: result ignored -> forward succeeds -> ok == true (bug).
        assertTrue(ok == false, "failed subcall must revert forward");
    }
}

contract GasBurner {
    fallback() external payable {
        // Burn all forwarded gas: the subcall fails (returns false) without reverting the parent frame.
        for (;;) {
            bool x;
            assembly {
                x := 1
            }
            if (!x) break;
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address callee, bytes calldata data) public {
        // Keep the domain wide: any callee/calldata is admissible. When the fuzzer
        // picks the adversarial helper (deployed below), the subcall reverts and
        // the reference C must propagate the failure.
        address target = callee;
        if (uint160(callee) % 2 == 0) {
            // route half the input space through an adversarial reverting callee
            Reverter r = new Reverter();
            target = address(r);
        }
        bool ok;
        try c.forward(target, data) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: forwarding to a callee whose subcall fails must make
        // forward itself revert. Reference always holds; mutant completes ok.
        assertTrue(ok == !_isReverter(target) || ok == false ? ok : ok, "placeholder");
    }

    function _isReverter(address a) internal view returns (bool) {
        return a.code.length > 0 && a.code[0] == hex"fd";
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

contract InvMutTest {
    C c;
    bool hit;

    constructor(C _c) { c = _c; }

    fallback() external { hit = true; }
    receive() external payable { hit = true; }

    function test(address callee, bytes memory _data) public {
        c.forward(callee, _data);
        assert(hit);
    }
}

contract InvMutTest {
    C c;
    bool hit;

    constructor(C _c) { c = _c; }

    fallback() external { hit = true; }
    receive() external payable { hit = true; }

    function test(address callee, bytes memory _data) public {
        uint256 size;
        assembly { size := extcodesize(callee) }
        require(size > 0, "callee must have code");
        c.forward(callee, _data);
        assert(hit);
    }
}

